const input = $input.all();

const seen = new Set();
const cleaned = [];

function getValue(row, keys) {
  for (const key of keys) {
    if (row[key] !== undefined && row[key] !== null && row[key] !== '') {
      return row[key];
    }
  }
  return null;
}

function getDate(value) {
  if (typeof value === 'number' || /^\d{10,13}$/.test(String(value))) {
    const n = Number(value);
    return new Date(n < 1e12 ? n * 1000 : n);
  }
  return new Date(value);
}

for (const item of input) {
  const row = item.json;

  const text = String(
    getValue(row, ['text', 'content', 'reviewText', 'review']) || ''
  ).trim();

  const dateValue = getValue(row, ['date', 'at', 'reviewDate']);
  const rating = Number(getValue(row, ['rating', 'score', 'stars']));

  if (!text || text.split(/\s+/).filter(Boolean).length < 5) continue;
  if (!dateValue || !Number.isFinite(rating)) continue;

  const date = getDate(dateValue);
  if (Number.isNaN(date.getTime())) continue;

  const reviewId = getValue(row, ['reviewId', 'review_id', 'id']);

  const duplicateKey = reviewId
    ? String(reviewId)
    : `${text.toLowerCase()}|${date.toISOString()}|${rating}`;

  if (seen.has(duplicateKey)) continue;
  seen.add(duplicateKey);

  // Monday of the review's calendar week
  const weekDate = new Date(date);
  weekDate.setUTCHours(0, 0, 0, 0);
  const day = weekDate.getUTCDay();
  weekDate.setUTCDate(weekDate.getUTCDate() - (day === 0 ? 6 : day - 1));

  cleaned.push({
    ...row,
    reviewId: reviewId || duplicateKey,
    text,
    date: date.toISOString(),
    rating,
    week_start: weekDate.toISOString().slice(0, 10)
  });
}

// Keep no more than 200 reviews per week
const weeklyCounts = {};
const limitedReviews = [];

for (const review of cleaned) {
  const week = review.week_start;
  weeklyCounts[week] = weeklyCounts[week] || 0;

  if (weeklyCounts[week] < 200) {
    limitedReviews.push(review);
    weeklyCounts[week]++;
  }
}

return [{
  json: {
    totalInput: input.length,
    totalAfterCleaning: cleaned.length,
    totalReviews: limitedReviews.length,
    weeklyCounts,
    reviews: limitedReviews
  }
}];

const data = $input.first().json;
const reviews = data.reviews;

// Select up to 30 reviews per rating for a balanced sample
const sample = [];

for (const rating of [1, 2, 3, 4, 5]) {
  const group = reviews.filter(r => Number(r.rating) === rating);
  const count = Math.min(30, group.length);

  for (let i = 0; i < count; i++) {
    const index = Math.floor(i * group.length / count);
    sample.push(group[index]);
  }
}

const reviewText = sample.map(r =>
  `ID: ${r.reviewId}\nRating: ${r.rating}\nReview: ${r.text.slice(0, 300)}`
).join('\n\n');

return [{
  json: {
    totalReviews: reviews.length,
    sampleSize: sample.length,
    reviewText
  }
}];

const result = $input.first().json;

return [{
  json: {
    themes: result.output.themes
  }
}];

const themes = $('Store Discovered Themes').first().json.themes;
const reviews = $('Clean and Prepare Reviews').first().json.reviews;

const batchSize = 50;
const startBatch = 2; // B01 is already saved
const batches = [];

for (let i = 0; i < reviews.length; i += batchSize) {
  batches.push({
    batchNumber: batches.length + 1,
    reviews: reviews.slice(i, i + batchSize)
  });
}

return batches
  .filter(batch => batch.batchNumber >= startBatch)
  .map(batch => ({
    json: {
      batchNumber: batch.batchNumber,
      totalBatches: batches.length,
      themes,
      reviews: batch.reviews.map(r => ({
        reviewId: r.reviewId,
        rating: r.rating,
        text: r.text.slice(0, 300)
      }))
    }
  }));

