const reviews = $('Clean and Prepare Reviews').first().json.reviews;

const keywords = [
  'charge',
  'charges',
  'fee',
  'fees',
  'brokerage',
  'hidden',
  'deducted'
];

const filtered = reviews.filter(review => {
  const text = review.text.toLowerCase();
  return keywords.some(keyword => text.includes(keyword));
});

return [{
  json: {
    totalReviews: reviews.length,
    feeRelatedCount: filtered.length,
    feeReviews: filtered
  }
}];

const reviews = $('Filter Fee Related Reviews').first().json.feeReviews;

const batch = reviews.slice(0, 25);

return [{
  json: {
    totalFeeReviews: reviews.length,
    sampleSize: batch.length,
    reviews: batch.map(r => ({
      reviewId: r.reviewId,
      rating: r.rating,
      text: r.text.slice(0, 300)
    }))
  }
}];

