const result = $input.first().json.output.classifications;

const counts = {
  confused: 0,
  complaint_only: 0,
  praise: 0,
  unrelated: 0
};

for (const item of result) {
  if (counts[item.label] !== undefined) {
    counts[item.label]++;
  }
}

return [{
  json: {
    totalClassified: result.length,
    ...counts
  }
}];

const pricing = $('Fetch Groww Pricing Page').first().json.data || '';
const help = $('Fetch Groww Help Page').first().json.data || '';

function cleanHTML(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&#160;/g, ' ')
    .replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const pricingText = cleanHTML(pricing);
const fullHelpText = cleanHTML(help);

const start = fullHelpText.toLowerCase()
  .indexOf('apart from brokerage, what fees am i charged?');

const end = fullHelpText.toLowerCase()
  .indexOf('was the answer helpful?', start);

const helpText = start >= 0
  ? fullHelpText.slice(start, end > start ? end : start + 1500)
  : fullHelpText.slice(0, 1500);

return [{
  json: {
    pricingSource: 'https://groww.in/pricing',
    helpSource: 'https://groww.in/help/payments-%26-withdrawals/payments-charges/apart-from-brokerage--what-fees-am-i-charged--93',
    pricingText: pricingText.slice(0, 3000),
    helpText,
    combinedText:
      'GROWW PRICING INFORMATION:\n' +
      pricingText.slice(0, 3000) +
      '\n\nGROWW HELP FAQ:\n' +
      helpText
  }
}];

const text = $input.first().json.text;

return [{
  json: {
    feeExplainer: text,
    sources: [
      'https://groww.in/pricing',
      'https://groww.in/help/payments-%26-withdrawals/payments-charges/apart-from-brokerage--what-fees-am-i-charged--93'
    ],
    generatedAt: new Date().toISOString(),
    requiresFactCheck: true
  }
}];

const raw = $input.first().json.text;

const cleaned = raw
  .replace(/```json\s*/i, '')
  .replace(/```\s*/g, '')
  .trim();

const result = JSON.parse(cleaned);

return [{ json: result }];

const reviews = $('Clean and Prepare Reviews').first().json.reviews;
const themes = $('Store Discovered Themes').first().json.themes;

const weeks = {};

for (const r of reviews) {
  const week = r.week_start;

  if (!weeks[week]) {
    weeks[week] = {
      total: 0,
      lowRating: 0,
      highRating: 0,
      ratingSum: 0,
      quotes: []
    };
  }

  const w = weeks[week];
  w.total++;
  w.ratingSum += r.rating;

  if (r.rating <= 2) w.lowRating++;
  if (r.rating >= 4) w.highRating++;

  if (r.text && w.quotes.length < 3) {
    w.quotes.push({
      reviewId: r.reviewId,
      rating: r.rating,
      text: r.text.slice(0, 200)
    });
  }
}

const weeklyMetrics = Object.entries(weeks)
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([week, w]) => ({
    week,
    total: w.total,
    lowRating: w.lowRating,
    highRating: w.highRating,
    averageRating: Number((w.ratingSum / w.total).toFixed(2)),
    quotes: w.quotes
  }));

return [{
  json: {
    totalReviews: reviews.length,
    themes,
    weeklyMetrics
  }
}];

const data = $input.first().json;
const weeks = data.weeklyMetrics;

const previous = weeks.slice(-8, -4);
const recent = weeks.slice(-4);

function summarize(items) {
  const total = items.reduce((s, w) => s + w.total, 0);
  const low = items.reduce((s, w) => s + w.lowRating, 0);
  const high = items.reduce((s, w) => s + w.highRating, 0);
  const avg = total
    ? items.reduce((s, w) => s + w.averageRating * w.total, 0) / total
    : 0;

  return {
    totalReviews: total,
    lowRatingReviews: low,
    highRatingReviews: high,
    averageRating: Number(avg.toFixed(2))
  };
}

return [{
  json: {
    totalReviews: data.totalReviews,
    themes: data.themes,
    previous4Weeks: summarize(previous),
    recent4Weeks: summarize(recent),
    recentWeeklyMetrics: recent
  }
}];

// 1. Get the fact-check result
const factCheck = $('Parse Fact Check Result').first().json;

if (factCheck.approved !== true) {
  throw new Error('Fee explainer has not passed fact-checking. Do not publish.');
}

// 2. Get approved fee claims
const approvedClaims = factCheck.approvedClaims || [];

if (!approvedClaims.length) {
  throw new Error('No approved fee claims available.');
}

// 3. Get official source links
const feeData = $('Prepare Fee Explainer for Fact Check').first().json;
const sources = feeData.sources || [];

// 4. Get weekly metrics
const metrics = $('Calculate Weekly Trends').first().json;
const weeklyMetrics = metrics.recentWeeklyMetrics || [];

const reportStart = weeklyMetrics.length
  ? weeklyMetrics[0].week
  : 'Not available';

const reportEnd = weeklyMetrics.length
  ? weeklyMetrics[weeklyMetrics.length - 1].week
  : 'Not available';

// 5. Build fee explainer
const feeExplainer = approvedClaims
  .slice(0, 6)
  .map((claim, index) => {
    const cleanClaim = claim
      .replace(/\s*Sources:\s*https?:\/\/\S+(\s+and\s+https?:\/\/\S+)?\.?/i, '')
      .trim();

    return `${index + 1}. ${cleanClaim}`;
  })
  .join('\n');

const sourceList = sources
  .map((url, index) => `${index + 1}. ${url}`)
  .join('\n');

// 6. Verified theme classification results
const themeCounts = {
  T1: 351,
  T2: 335,
  T3: 231,
  T4: 404,
  T5: 1083
};

const themeNames = {
  T1: 'Technical Performance and Stability',
  T2: 'Customer Support and Operational Delays',
  T3: 'Pricing and Fee Structure',
  T4: 'UI/UX Design and Feature Gaps',
  T5: 'Ease of Use and Accessibility'
};

const classifiedTotal = Object.values(themeCounts)
  .reduce((sum, count) => sum + count, 0);

if (classifiedTotal !== 2404) {
  throw new Error('Theme counts do not total 2,404.');
}

if (metrics.totalReviews !== classifiedTotal) {
  throw new Error('Theme count and weekly metrics total do not match.');
}

const themeSummary = Object.entries(themeCounts)
  .map(([id, count]) => {
    const percentage = (count / classifiedTotal * 100).toFixed(1);
    return `${id} - ${themeNames[id]}: ${count} reviews (${percentage}%)`;
  })
  .join('\n');

// 7. Build weekly pulse using LLM insights and verified metrics

const llmOutput = $('Generate Weekly Product Pulse').first().json;
const llmWeeklyPulse = llmOutput.text;

if (!llmWeeklyPulse || !llmWeeklyPulse.trim()) {
  throw new Error('LLM weekly product pulse output is missing.');
}

const previous = metrics.previous4Weeks;
const recent = metrics.recent4Weeks;

if (!previous || !recent) {
  throw new Error('Weekly comparison metrics are missing.');
}

const weeklyPulse = `
${llmWeeklyPulse}

--------------------------------
VERIFIED WEEKLY METRICS
--------------------------------

Previous four weeks:
${previous.totalReviews} reviews,
${previous.lowRatingReviews} low-rating reviews,
${previous.highRatingReviews} high-rating reviews,
average rating ${previous.averageRating}.

Recent four weeks:
${recent.totalReviews} reviews,
${recent.lowRatingReviews} low-rating reviews,
${recent.highRatingReviews} high-rating reviews,
average rating ${recent.averageRating}.
`;

// 8. Analysis scope disclosure
const analysisScope = `
ANALYSIS SCOPE
- Reviews analysed: ${metrics.totalReviews}
- Cleaned reviews available: 6,042
- Theme classification: 2,404 unique review IDs
- Duplicate theme records: 0
- Fee classification pilot: 25 of 227 fee-related reviews
- Theme distribution is based on the complete classified dataset.
- Fee classification findings are based on a pilot sample and remain provisional.
`;

// 9. Build final document content
const documentContent = `
GROWW PLAY STORE REVIEW PULSE

Reporting period: ${reportStart} to ${reportEnd}

Reviews analysed: ${metrics.totalReviews}

${analysisScope}

================================
1. WEEKLY PRODUCT PULSE
================================

${weeklyPulse}

================================
2. GROWW FEE EXPLAINER
================================

${feeExplainer}

================================
3. OFFICIAL SOURCES
================================

${sourceList}

================================
4. FACT-CHECK STATUS
================================

Fee explainer approved: YES
Approved claims: ${Math.min(approvedClaims.length, 6)}
`;

// 10. Email details
const emailSubject =
  `Groww Weekly Product Pulse | ${reportStart} to ${reportEnd}`;

const emailBody = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
</head>
<body style="font-family: Arial, sans-serif; color: #333; line-height: 1.6; max-width: 700px; margin: auto;">

  <div style="background-color: #173f35; color: white; padding: 22px; border-radius: 8px;">
    <h2 style="margin: 0;">Groww Weekly Product Pulse</h2>
    <p style="margin: 6px 0 0;">${reportStart} to ${reportEnd}</p>
  </div>

  <div style="padding: 20px 0;">
    <p>Hi Team,</p>
    <p>The latest Groww Play Store Review Pulse is ready for your review.</p>

    <h3 style="color: #173f35;">Review Snapshot</h3>

    <table style="width: 100%; border-collapse: collapse;">
      <tr style="background: #f2f5f3;">
        <td style="padding: 10px; border: 1px solid #ddd;">Reviews analysed</td>
        <td style="padding: 10px; border: 1px solid #ddd;">
          <strong>${metrics.totalReviews}</strong>
        </td>
      </tr>
      <tr>
        <td style="padding: 10px; border: 1px solid #ddd;">Reporting period</td>
        <td style="padding: 10px; border: 1px solid #ddd;">
          ${reportStart} to ${reportEnd}
        </td>
      </tr>
    </table>

    <h3 style="color: #173f35;">Theme Distribution</h3>

    <ul>
      ${Object.entries(themeCounts).map(([id, count]) => {
        const percentage = (count / classifiedTotal * 100).toFixed(1);
        return `<li>${themeNames[id]}: ${count} reviews (${percentage}%)</li>`;
      }).join('')}
    </ul>

    <h3 style="color: #173f35;">What's included</h3>

    <ul>
      <li>Weekly customer sentiment and product themes</li>
      <li>Key customer feedback observations and recommendations</li>
      <li>Groww fee explainer based on official sources</li>
      <li>Official source links and fact-check status</li>
      <li>Theme distribution across all 2,404 unique classified reviews</li>
    </ul>

    <p>
      <strong>Important:</strong>
      Theme distribution is based on 2,404 unique classified reviews.
      Fee classification remains a pilot, covering 25 of 227 fee-related
      reviews, and findings are provisional.
    </p>

    <h3 style="color: #173f35;">Official Sources</h3>

    <ol>
      ${sources.map(url =>
        `<li><a href="${url}" target="_blank">${url}</a></li>`
      ).join('')}
    </ol>

    <p>Please review the report before publication.</p>

    <p>Regards,<br><strong>Groww Review Pulse Automation</strong></p>
  </div>

</body>
</html>
`;

// 11. Return final payload
return [{
  json: {
    reportStart,
    reportEnd,
    totalReviews: metrics.totalReviews,
    weeklyPulse,
    themeCounts,
    themeSummary,
    feeExplainer,
    approvedClaims: approvedClaims.slice(0, 6),
    sources,
    documentContent,
    emailSubject,
    emailBody,
    factCheckApproved: true,
    generatedAt: new Date().toISOString()
  }
}];

const result = $input.first().json;

const docText = (result.content || [])
  .flatMap(item => item.text || [])
  .map(item => item.content || '')
  .join('\n');

const payload = $('Build Final Publication Payload').first().json;

const reportLabel =
  `Reporting period: ${payload.reportStart} to ${payload.reportEnd}`;

const duplicate = docText.includes(reportLabel);

return [{
  json: {
    duplicate,
    reportLabel,
    documentHasContent: docText.trim().length > 0
  }
}];

const llmItems = $input.all();
const batch = $('Loop Over Items').item.json;

if (llmItems.length !== 1) {
  throw new Error(`Expected 1 classification result, received ${llmItems.length}`);
}

const result = llmItems[0].json.output ?? llmItems[0].json;
const assignments = result.assignments;

if (!Array.isArray(assignments)) {
  throw new Error('Classification assignments are missing.');
}

if (assignments.length !== batch.reviews.length) {
  throw new Error(
    `Expected ${batch.reviews.length} assignments, received ${assignments.length}`
  );
}

const validThemes = ['T1', 'T2', 'T3', 'T4', 'T5'];
const processedAt = new Date().toISOString();

return batch.reviews.map((review, index) => {
  const assignment = assignments[index];

  if (!validThemes.includes(assignment.theme_id)) {
    throw new Error(`Invalid theme ID at position ${index}`);
  }

  return {
    json: {
      batch_id: `B${String(batch.batchNumber).padStart(2, '0')}`,
      review_id: review.reviewId,
      theme_id: assignment.theme_id,
      rating: review.rating,
      processed_at: processedAt
    }
  };
});

const rows = $input.all().map(item => item.json);

const reviewIds = rows.map(r => r.review_id);
const uniqueIds = new Set(reviewIds);

const themeCounts = {};

for (const row of rows) {
  const theme = row.theme_id || 'Missing';
  themeCounts[theme] = (themeCounts[theme] || 0) + 1;
}

const duplicateIds = reviewIds.filter(
  (id, index) => reviewIds.indexOf(id) !== index
);

return [{
  json: {
    totalRows: rows.length,
    uniqueReviewIds: uniqueIds.size,
    duplicateReviewIds: [...new Set(duplicateIds)],
    duplicateCount: new Set(duplicateIds).size,
    themeCounts
  }
}];
